package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.CorrectionRefusedException;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * The people's plans: an amount from a start date every so many days (at least 1), or monthly on a
 * day of the month (1 to 31), one or the other, up to an end date on or after it. Generating makes, for every plan on the sheet in the order they were added, a DRAFT
 * claim with the plan's amount and an empty note for each plan date up to its end and the sheet's
 * today that it has made none for yet, dated that day and added by every rule of the claim form. A
 * date the form refuses is skipped, and tried again by the next generate. Each claim is made in its
 * own transaction, so one refused leaves the others made.
 */
@Service
public class ClaimPlanService {

    private final ClaimPlanRepository plans;
    private final ClaimPlanDateRepository dates;
    private final PersonRepository people;
    private final SheetRepository sheetRows;
    private final SheetService sheets;
    private final ClaimService claims;
    private final TransactionTemplate transaction;
    private final Audit audit;

    public ClaimPlanService(ClaimPlanRepository plans, ClaimPlanDateRepository dates, PersonRepository people,
            SheetRepository sheetRows, SheetService sheets, ClaimService claims,
            PlatformTransactionManager transactions, Audit audit) {
        this.plans = plans;
        this.dates = dates;
        this.people = people;
        this.sheetRows = sheetRows;
        this.sheets = sheets;
        this.claims = claims;
        this.transaction = new TransactionTemplate(transactions);
        this.audit = audit;
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<ClaimPlan> plans(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** How many claims each of the sheet's plans has made so far, by plan id (those with none left out). */
    @Transactional(readOnly = true)
    public Map<Long, Integer> made(String sheetId) {
        Map<Long, Integer> made = new HashMap<>();
        for (ClaimPlanDate d : dates.findBySheetId(sheetId)) made.merge(d.getPlanId(), 1, Integer::sum);
        return made;
    }

    @Transactional
    public ClaimPlan add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate start,
            Integer every, Integer day, LocalDate end) {
        sheetRows.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if ((every == null) == (day == null) || end.isBefore(start)) throw new PlanRefusedException();
        if (every != null && every < 1) throw new PlanRefusedException();
        if (day != null && (day < 1 || day > 31)) throw new PlanRefusedException();
        ClaimPlan plan = plans.saveAndFlush(new ClaimPlan(sheetId, personId, amount, start, every, day, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
                + " amount=" + amount.toPlainString() + " start=" + start
                + (day != null ? " day=" + day : " every=" + every) + " end=" + end);
        return plan;
    }

    /** Make the plans' claims due by the sheet's today: how many were made. */
    public int generate(String sheetId, String user) {
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        for (ClaimPlan plan : plans(sheetId)) {
            for (LocalDate on : plan.datesUpTo(today)) {
                try {
                    Boolean done = transaction.execute(status -> make(sheetId, user, plan, on));
                    if (Boolean.TRUE.equals(done)) made++;
                } catch (PeriodClosedException | PersonRetiredException | PersonNotFoundException
                        | CorrectionRefusedException refused) {
                    // skipped: tried again next time
                }
            }
        }
        return made;
    }

    /** Make the plan's claim for the date unless it has made one for it: whether it made one. */
    private boolean make(String sheetId, String user, ClaimPlan plan, LocalDate on) {
        sheetRows.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        if (dates.existsByPlanIdAndMadeOn(plan.getId(), on)) return false;
        claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), on, "", null);
        dates.saveAndFlush(new ClaimPlanDate(sheetId, plan.getId(), on));
        return true;
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimPlanController {

    /**
     * A plan on the sheet; its amount has two decimals, every or day is set (the other null), and generated is how
     * many claims it has made so far.
     */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated) {
        static PlanView of(ClaimPlan plan, int generated) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().setScale(2).toPlainString(),
                    plan.getStart(), plan.getEvery(), plan.getDay(), plan.getEnd(), generated);
        }
    }

    /**
     * A plan's amount (as the claim form takes one that corrects none: 0.00 or more, at most two
     * decimals), start date, either every how many days (a whole number, at least 1) or the day of the month it runs
     * on monthly (1 to 31), and end date (on or after the start).
     */
    public record PlanRequest(
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount,
            @NotNull LocalDate start,
            @Min(1) @Max(36600) Integer every,
            @Min(1) @Max(31) Integer day,
            @NotNull LocalDate end) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }
    }

    /** How many claims a generate made. */
    public record GenerateView(int generated) {}

    private final ClaimPlanService service;

    public ClaimPlanController(ClaimPlanService service) {
        this.service = service;
    }

    @GetMapping("/plans")
    public List<PlanView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, Integer> made = service.made(sheetId);
        return service.plans(sheetId).stream().map(p -> PlanView.of(p, made.getOrDefault(p.getId(), 0))).toList();
    }

    @PostMapping("/people/{personId}/plans")
    public PlanView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PlanRequest request) {
        return PlanView.of(service.add(sheetId, user, personId, request.amountValue(), request.start(),
                request.every(), request.day(), request.end()), 0);
    }

    @PostMapping("/plans/generate")
    public GenerateView generate(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new GenerateView(service.generate(sheetId, user));
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * A person's plan: an amount on its start date and every so many days after, or monthly on a day of
 * the month (from the start's month, a day beyond the month's length falling on its last day, dates
 * before the start left out), up to its end date.
 */
@Entity
@Table(name = "claim_plan")
public class ClaimPlan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_on", nullable = false)
    private LocalDate start;

    /** Every how many days; none when the plan runs monthly. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) a monthly plan runs on; none when it runs every so many days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_on", nullable = false)
    private LocalDate end;

    protected ClaimPlan() {}

    public ClaimPlan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public BigDecimal getAmount() { return amount; }

    public LocalDate getStart() { return start; }

    public Integer getEvery() { return every; }

    public Integer getDay() { return day; }

    public LocalDate getEnd() { return end; }

    /**
     * The plan's dates up to its end and the day given: the start then every so many days, or its day
     * in every month from the start's month (the month's last day when shorter), none before the start.
     */
    public List<LocalDate> datesUpTo(LocalDate upTo) {
        LocalDate last = end.isBefore(upTo) ? end : upTo;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last)) dates.add(d);
            }
        } else {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) dates.add(d);
        }
        return dates;
    }
}

